mapper.delete:

DELETE FROM monitor_sys_gen_server_alert_history
WHERE monitor_sys_gen_server_alert_history_trigger_time < #{expireTime}
AND monitor_sys_gen_server_alert_history_status IN ('RECOVERED', 'IGNORED')

mapper.select:
SELECT monitor_sys_gen_server_alert_history_level as level, monitor_sys_gen_server_alert_history_status as status, COUNT(*) as count FROM monitor_sys_gen_server_alert_history WHERE 1=1
AND monitor_sys_gen_server_alert_history_server_id = #{serverId}
AND monitor_sys_gen_server_alert_history_trigger_time >= #{startTime}
AND monitor_sys_gen_server_alert_history_trigger_time <= #{endTime}
GROUP BY monitor_sys_gen_server_alert_history_level, monitor_sys_gen_server_alert_history_status ORDER BY level, status


SELECT * FROM monitor_sys_gen_server_alert_history
WHERE monitor_sys_gen_server_alert_history_fingerprint = #{fingerprint}
AND monitor_sys_gen_server_alert_history_trigger_time >= #{startTime}
ORDER BY monitor_sys_gen_server_alert_history_trigger_time DESC

SELECT DATE(monitor_sys_gen_server_alert_history_trigger_time) as alertDate, monitor_sys_gen_server_alert_history_level as level, monitor_sys_gen_server_alert_history_type as type, monitor_sys_gen_server_alert_history_status as status, COUNT(*) as count FROM monitor_sys_gen_server_alert_history WHERE 1=1
AND monitor_sys_gen_server_alert_history_server_id = #{serverId}
AND monitor_sys_gen_server_alert_history_trigger_time >= #{startTime}
AND monitor_sys_gen_server_alert_history_trigger_time <= #{endTime}
GROUP BY DATE(monitor_sys_gen_server_alert_history_trigger_time), monitor_sys_gen_server_alert_history_level, monitor_sys_gen_server_alert_history_type, monitor_sys_gen_server_alert_history_status ORDER BY alertDate DESC, level, type, status

SELECT DATE(monitor_sys_gen_server_alert_history_trigger_time) as trendDate, HOUR(monitor_sys_gen_server_alert_history_trigger_time) as trendHour, monitor_sys_gen_server_alert_history_level as level, COUNT(*) as alertCount, COUNT(CASE WHEN monitor_sys_gen_server_alert_history_status = 'TRIGGERED' THEN 1 END) as triggeredCount, COUNT(CASE WHEN monitor_sys_gen_server_alert_history_status = 'RECOVERED' THEN 1 END) as recoveredCount, COUNT(CASE WHEN monitor_sys_gen_server_alert_history_status = 'IGNORED' THEN 1 END) as ignoredCount FROM monitor_sys_gen_server_alert_history WHERE 1=1
AND monitor_sys_gen_server_alert_history_server_id = #{serverId}
AND monitor_sys_gen_server_alert_history_trigger_time >= #{startTime}
AND monitor_sys_gen_server_alert_history_trigger_time <= #{endTime}
GROUP BY DATE(monitor_sys_gen_server_alert_history_trigger_time), HOUR(monitor_sys_gen_server_alert_history_trigger_time), monitor_sys_gen_server_alert_history_level ORDER BY trendDate DESC, trendHour DESC, level
